// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, address newOwner) public {
        vm.assume(actor != address(this)); // this deployed c and owns it
        vm.prank(actor);
        bool ok;
        try c.transferOwnership(newOwner) { ok = true; } catch { ok = false; }
        // Universal rule: a non-owner caller can never change ownership.
        assertTrue(!ok && c.owner() == address(this));
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address owner;

    function setUp() public {
        c = new C();
        owner = address(0xA11CE);
        vm.prank(owner);
        c.initialize();
    }

    function testFuzz_property(address newImpl) public {
        vm.assume(newImpl != owner);
        bool ok;
        vm.prank(owner);
        try c.updateRoundImplementation(payable(newImpl)) {
            ok = true;
        } catch {
            ok = false;
        }
        // Rule: roundImplementation is always set to a non-zero address that
        // equals the requested value whenever the call succeeds; zero address
        // is always rejected.
        assertTrue(
            (ok && c.roundImplementation() == newImpl && newImpl != address(0)) ||
            (!ok && c.roundImplementation() == address(0)),
            "roundImplementation must be a non-zero requested address or the call must revert"
        );
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address owner;

    function setUp() public {
        c = new C();
        owner = address(0xA11CE);
        vm.prank(owner);
        c.initialize();
    }

    function testFuzz_property(address actor, address newImpl) public {
        // wide domain: no restriction on newImpl (zero included), actor may be anyone
        vm.prank(actor);
        bool ok;
        try c.updateRoundImplementation(payable(newImpl)) {
            ok = true;
        } catch {
            ok = false;
        }
        // General rule: whenever the update call succeeds, the stored round
        // implementation is a real (non-zero) address — the reference rejects
        // the zero address so success implies non-zero storage; the mutant
        // succeeds on newImpl == address(0) and stores it, violating the rule.
        assertTrue(!ok || c.roundImplementation() != address(0));
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
        c.initialize(); // this contract becomes the owner
    }

    function testFuzz_property(address impl) public {
        // Admissible domain: the entire address space, including address(0).
        bool ok;
        vm.prank(address(this)); // owner call
        try c.updateRoundImplementation(payable(impl)) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: updateRoundImplementation(x) succeeds if and only if
        // x != address(0), and on success roundImplementation() == x.
        if (impl != address(0)) {
            assertTrue(ok && c.roundImplementation() == impl);
        } else {
            assertTrue(!ok);
        }
    }
}

