pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
        c.initialize();
    }

    function testFuzz_property(address actor, address payable newImpl) public {
        vm.assume(actor != address(0));
        vm.assume(newImpl != address(0));
        vm.startPrank(actor);
        c.updateAlloSettings(address(0x1));
        c.updateRoundImplementation(newImpl);
        vm.stopPrank();
        assertTrue(c.roundImplementation() == newImpl);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function test(address payable newImpl) external {
        require(newImpl != address(0));

        (bool ok, ) = address(c).call(
            abi.encodeWithSelector(c.updateRoundImplementation.selector, newImpl)
        );

        assert(ok == (c.owner() == address(this)));
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address newImpl) public payable {
        require(true);
        address before = c.roundImplementation();
        bool reverted; try c.updateRoundImplementation(payable(newImpl)) { reverted = false; } catch { reverted = true; }
        assert(reverted && c.roundImplementation() == before);
    }
    receive() external payable {}
}

